"use client";

import { FormEvent, useCallback, useEffect, useMemo, useState } from "react";
import { Activity, Archive, ArrowDownLeft, ArrowUpRight, CalendarClock, CircleDollarSign, CreditCard, Landmark, Plus, RefreshCw, ShieldCheck, Target, WalletCards } from "lucide-react";
import { FINANCE_CURRENCIES, estimateMonthlyDebtPayoff, formatFinanceAmount, parseFinanceAmount, type FinanceCurrency } from "@/lib/personal-workspace-finance-core";
import { LiquidLensSurface } from "@/components/ui/LiquidLensSurface";
import { WorkspaceSectionNav } from "@/components/workspace/WorkspaceSectionNav";

type Transaction = { id: string; kind: string; quality: string; amount: string; currency: FinanceCurrency; occurredOn: string; label: string; category: string; description?: string | null; notes?: string | null; paymentMethod?: string | null; fromAccount?: string | null; toAccount?: string | null; deletedAt?: string | null; attachments?: Array<{ id: string; mediaAsset: { id: string; mimeType: string; byteSize: number } }> };
type Position = { id: string; kind: "ASSET" | "LIABILITY"; label: string; category: string; currency: FinanceCurrency; value: string; quality: string; valuedOn: string; revision: number; valuations: Array<{ id: string; value: string; quality: string; valuedOn: string; createdAt: string }> };
type Budget = { id: string; name: string; category: string; currency: FinanceCurrency; limitAmount: string; startsOn: string; endsOn: string; spent: string; remaining: string; percent: number; calculationTruncated?: boolean };
type Goal = { id: string; name: string; description?: string | null; currency: FinanceCurrency; targetAmount: string; currentAmount: string; targetOn?: string | null; progressPercent: number; status: string; movements?: Array<{ id: string; kind: string; amount: string; occurredOn: string; transaction: { label: string; amount: string; currency: string } }> };
type Debt = { id: string; name: string; lenderDescription?: string | null; currency: FinanceCurrency; originalPrincipal: string; outstandingBalance: string; annualInterestRate?: string | null; interestType: string; repaymentFrequency: string; repaymentAmount?: string | null; nextDueOn?: string | null; payments?: Array<{ id: string; principalAmount: string; interestAmount: string; occurredOn: string; transaction: { label: string; amount: string; currency: string } }> };
type Schedule = { id: string; kind: string; quality: string; amount: string; currency: FinanceCurrency; label: string; category: string; frequency: string; interval: number; nextOn: string; active: boolean };
type Reminder = { id: string; kind: string; title: string; remindAt: string; timezone: string; taskId?: string | null; status: string };
type Data = { workspace: { timezone: string } | null; summary: Array<Record<string, string | number>>; transactions: { items: Transaction[]; total: number; page: number; pageSize: number; truncated?: boolean }; positions: Position[]; budgets: Budget[]; goals: Goal[]; debts: Debt[]; recurring: Schedule[]; reminders: Reminder[]; history: Array<{ id: string; action: string; targetType: string; targetId: string; changedFields: string[]; createdAt: string }> };
type Resource = "transactions" | "positions" | "budgets" | "goals" | "debts" | "recurring" | "reminders";
type Tab = "overview" | Resource;
type EditField = { key: string; label: string; type?: "text" | "number" | "date" | "datetime-local" | "textarea" | "select"; options?: readonly string[]; required?: boolean };
const tabs: Array<{ id: Tab; label: string }> = [{ id: "overview", label: "Overview" }, { id: "transactions", label: "Ledger" }, { id: "positions", label: "Assets & liabilities" }, { id: "budgets", label: "Budgets" }, { id: "goals", label: "Goals" }, { id: "debts", label: "Debt" }, { id: "recurring", label: "Recurring" }, { id: "reminders", label: "Reminders" }];
const editFields: Partial<Record<Resource, EditField[]>> = {
  positions: [{ key: "kind", label: "Type", type: "select", options: ["ASSET", "LIABILITY"], required: true }, { key: "label", label: "Name", required: true }, { key: "category", label: "Category", required: true }, { key: "value", label: "Value", type: "number", required: true }, { key: "quality", label: "Quality", type: "select", options: ["ACTUAL", "ESTIMATE"], required: true }, { key: "valuedOn", label: "Valuation date", type: "date", required: true }, { key: "notes", label: "Private notes", type: "textarea" }],
  budgets: [{ key: "name", label: "Budget name", required: true }, { key: "category", label: "Category", required: true }, { key: "limitAmount", label: "Period limit", type: "number", required: true }, { key: "startsOn", label: "Starts", type: "date", required: true }, { key: "endsOn", label: "Ends", type: "date", required: true }],
  goals: [{ key: "name", label: "Goal name", required: true }, { key: "description", label: "Description", type: "textarea" }, { key: "targetAmount", label: "Target amount", type: "number", required: true }, { key: "targetOn", label: "Target date", type: "date" }],
  debts: [{ key: "name", label: "Debt name", required: true }, { key: "lenderDescription", label: "Lender description" }, { key: "originalPrincipal", label: "Original principal", type: "number", required: true }, { key: "outstandingBalance", label: "Outstanding balance", type: "number", required: true }, { key: "annualInterestRate", label: "Annual rate (%)", type: "number" }, { key: "interestType", label: "Rate type", type: "select", options: ["UNKNOWN", "FIXED", "VARIABLE"], required: true }, { key: "repaymentFrequency", label: "Repayment frequency", type: "select", options: ["IRREGULAR", "WEEKLY", "BIWEEKLY", "MONTHLY", "QUARTERLY", "ANNUAL"], required: true }, { key: "repaymentAmount", label: "Expected repayment", type: "number" }, { key: "nextDueOn", label: "Next due date", type: "date" }, { key: "notes", label: "Private assumptions", type: "textarea" }],
  recurring: [{ key: "kind", label: "Type", type: "select", options: ["INCOME", "EXPENSE", "TRANSFER"], required: true }, { key: "label", label: "Label", required: true }, { key: "category", label: "Category", required: true }, { key: "amount", label: "Amount", type: "number", required: true }, { key: "currency", label: "Currency", type: "select", options: FINANCE_CURRENCIES, required: true }, { key: "frequency", label: "Frequency", type: "select", options: ["WEEKLY", "MONTHLY", "ANNUAL"], required: true }, { key: "interval", label: "Every N periods", type: "number", required: true }, { key: "nextOn", label: "Next occurrence", type: "date", required: true }, { key: "fromAccount", label: "From account label" }, { key: "toAccount", label: "To account label" }],
  reminders: [{ key: "kind", label: "Reminder kind", type: "select", options: ["BILL_PAYMENT", "DEBT_REPAYMENT", "SAVINGS_CONTRIBUTION", "FINANCIAL_REVIEW", "BUDGET_CHECK_IN"], required: true }, { key: "title", label: "Reminder", required: true }, { key: "remindAt", label: "Date and time", type: "datetime-local", required: true }, { key: "timezone", label: "Time zone", required: true }],
};
const today = new Date().toISOString().slice(0, 10);
const firstOfYear = `${today.slice(0, 4)}-01-01`;
const fields = "min-h-11 w-full rounded-xl border border-white/10 bg-[#171613] px-3 text-sm text-white placeholder:text-white/35 focus:border-[#D9A441]/55 focus:outline-none";
const labelClass = "grid gap-1.5 text-xs text-white/55";
const button = "inline-flex min-h-10 items-center justify-center gap-2 rounded-xl border border-[#D9A441]/25 bg-[#D9A441]/10 px-3 text-xs font-medium text-[#F2CF86] transition hover:bg-[#D9A441]/20 disabled:cursor-not-allowed disabled:opacity-50";
const secondary = "inline-flex min-h-9 items-center justify-center gap-2 rounded-xl border border-white/10 px-3 text-xs text-white/65 transition hover:bg-white/[.06] disabled:opacity-40";
const currencyOptions = FINANCE_CURRENCIES.map((currency) => <option key={currency} value={currency}>{currency}</option>);
const defaultData: Data = { workspace: null, summary: [], transactions: { items: [], total: 0, page: 1, pageSize: 25 }, positions: [], budgets: [], goals: [], debts: [], recurring: [], reminders: [], history: [] };

export function WorkspaceFinance() {
  const [data, setData] = useState<Data>(defaultData);
  const [tab, setTab] = useState<Tab>("overview");
  const [currency, setCurrency] = useState<FinanceCurrency>("KES");
  const [from, setFrom] = useState(firstOfYear);
  const [to, setTo] = useState(today);
  const [applied, setApplied] = useState({ from: firstOfYear, to: today });
  const [kindFilter, setKindFilter] = useState("");
  const [search, setSearch] = useState("");
  const [page, setPage] = useState(1);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [error, setError] = useState("");
  const [notice, setNotice] = useState("");
  const [editing, setEditing] = useState<Transaction | null>(null);
  const [editingPosition, setEditingPosition] = useState<Position | null>(null);
  const [editingResource, setEditingResource] = useState<{ resource: Resource; id: string; record: Record<string, unknown> } | null>(null);

  const requestData = useCallback(async () => {
    const params = new URLSearchParams({ from: applied.from, to: applied.to, page: String(page), pageSize: "25" });
    if (kindFilter) params.set("kind", kindFilter);
    if (currency) params.set("currency", currency);
    if (search.trim()) params.set("q", search.trim().slice(0, 100));
    try {
      const response = await fetch(`/api/dashboard/workspace/finance?${params}`, { cache: "no-store", credentials: "same-origin" });
      const result = await response.json() as { success?: boolean; data?: Data; message?: string };
      if (!response.ok || !result.success || !result.data) throw new Error(result.message ?? "Finance records could not be loaded.");
      return result.data;
    } catch (cause) { throw new Error(cause instanceof Error ? cause.message : "Finance records could not be loaded."); }
  }, [applied, page, kindFilter, currency, search]);
  const load = useCallback(async () => {
    setLoading(true); setError("");
    try { setData(await requestData()); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Finance records could not be loaded."); }
    finally { setLoading(false); }
  }, [requestData]);
  useEffect(() => {
    let active = true;
    void requestData().then((next) => { if (active) setData(next); })
      .catch((cause: unknown) => { if (active) setError(cause instanceof Error ? cause.message : "Finance records could not be loaded."); })
      .finally(() => { if (active) setLoading(false); });
    return () => { active = false; };
  }, [requestData]);

  async function send(url: string, method: string, body?: unknown) {
    const response = await fetch(url, { method, credentials: "same-origin", cache: "no-store", headers: body === undefined ? undefined : { "Content-Type": "application/json" }, body: body === undefined ? undefined : JSON.stringify(body) });
    const result = await response.json() as { success?: boolean; data?: unknown; message?: string };
    if (!response.ok || !result.success) throw new Error(result.message ?? "The finance request could not be completed.");
    return result.data;
  }
  async function submit(event: FormEvent<HTMLFormElement>, resource: Resource) {
    event.preventDefault(); const form = event.currentTarget; const values = Object.fromEntries(new FormData(form).entries());
    const payload: Record<string, unknown> = { ...values };
    if (resource === "transactions") { payload.amount = String(values.amount); payload.occurredOn = String(values.occurredOn); }
    if (resource === "positions") { payload.value = String(values.value); payload.valuedOn = String(values.valuedOn); }
    if (resource === "budgets") { payload.limitAmount = String(values.limitAmount); }
    if (resource === "goals") { payload.targetAmount = String(values.targetAmount); payload.targetOn = values.targetOn || null; }
    if (resource === "debts") { payload.originalPrincipal = String(values.originalPrincipal); payload.outstandingBalance = String(values.outstandingBalance); payload.annualInterestRate = values.annualInterestRate || null; payload.repaymentAmount = values.repaymentAmount || null; payload.nextDueOn = values.nextDueOn || null; }
    if (resource === "recurring") { payload.amount = String(values.amount); payload.interval = Number(values.interval); }
    if (resource === "reminders") { payload.remindAt = new Date(String(values.remindAt)).toISOString(); payload.taskId = values.taskId || null; payload.timezone = data.workspace?.timezone || Intl.DateTimeFormat().resolvedOptions().timeZone; }
    setSaving(true); setError(""); setNotice("");
    try {
      if (resource === "positions" && editingPosition) { payload.expectedRevision = editingPosition.revision; await send(`/api/dashboard/workspace/finance/positions/${editingPosition.id}`, "PATCH", { data: payload }); setEditingPosition(null); }
      else await send("/api/dashboard/workspace/finance", "POST", { resource, data: payload });
      form.reset(); setNotice("Saved to your private Workspace Finance Centre."); await load();
    }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Record could not be saved."); }
    finally { setSaving(false); }
  }
  function startResourceEdit(resource: Resource, id: string, record: Record<string, unknown>) {
    setEditingResource({ resource, id, record }); setTab(resource); setError(""); setNotice(""); window.scrollTo({ top: 0, behavior: "smooth" });
  }
  async function submitResourceEdit(event: FormEvent<HTMLFormElement>) {
    event.preventDefault(); if (!editingResource) return;
    const values = Object.fromEntries(new FormData(event.currentTarget).entries()) as Record<string, FormDataEntryValue>;
    const payload: Record<string, unknown> = Object.fromEntries(Object.entries(values).map(([key, value]) => [key, String(value)]));
    for (const key of ["description", "notes", "lenderDescription", "repaymentAmount", "annualInterestRate", "nextDueOn", "targetOn", "fromAccount", "toAccount", "taskId"]) if (payload[key] === "") payload[key] = null;
    if (editingResource.resource === "recurring") payload.interval = Number(payload.interval);
    if (editingResource.resource === "reminders") payload.remindAt = new Date(String(payload.remindAt)).toISOString();
    if (editingResource.resource === "positions") payload.expectedRevision = editingResource.record.revision;
    setSaving(true); setError(""); setNotice("");
    try { await send(`/api/dashboard/workspace/finance/${editingResource.resource}/${encodeURIComponent(editingResource.id)}`, "PATCH", { data: payload }); setEditingResource(null); setNotice("Finance record updated."); await load(); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Finance record could not be updated."); }
    finally { setSaving(false); }
  }
  async function setRecurringActive(id: string, active: boolean) {
    setSaving(true); setError(""); setNotice("");
    try { await send(`/api/dashboard/workspace/finance/recurring/${encodeURIComponent(id)}`, "PATCH", { data: { active } }); setNotice(active ? "Recurring schedule resumed." : "Recurring schedule paused."); await load(); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Schedule could not be updated."); }
    finally { setSaving(false); }
  }
  async function archive(resource: Resource, id: string) {
    if (!window.confirm("Archive this finance record? It will no longer be included in active summaries.")) return;
    setSaving(true); setError("");
    try { await send(`/api/dashboard/workspace/finance/${resource}/${encodeURIComponent(id)}`, "DELETE"); setNotice("Record archived."); await load(); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Record could not be archived."); }
    finally { setSaving(false); }
  }
  async function action(payload: Record<string, unknown>) {
    setSaving(true); setError(""); setNotice("");
    try { await send("/api/dashboard/workspace/finance/actions", "POST", payload); setNotice("Finance activity recorded."); await load(); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Action could not be completed."); }
    finally { setSaving(false); }
  }
  async function uploadAttachment(transactionId: string, file: File) {
    setSaving(true); setError(""); setNotice("");
    let assetId: string | null = null;
    try {
      const form = new FormData(); form.set("file", file);
      const upload = await fetch("/api/dashboard/workspace/media", { method: "POST", credentials: "same-origin", body: form });
      const uploaded = await upload.json() as { success?: boolean; asset?: { id: string }; message?: string };
      if (!upload.ok || !uploaded.success || !uploaded.asset) throw new Error(uploaded.message ?? "Private image upload failed.");
      assetId = uploaded.asset.id;
      await send(`/api/dashboard/workspace/finance/transactions/${transactionId}/attachments`, "POST", { assetId });
      setNotice("Private image attached to this ledger entry."); await load();
    } catch (cause) {
      if (assetId) { try { await send(`/api/dashboard/workspace/media/${assetId}`, "DELETE"); } catch { /* An unlinked private asset can be removed in the private media library. */ } }
      setError(cause instanceof Error ? cause.message : "Private attachment could not be saved.");
    } finally { setSaving(false); }
  }
  async function detachAttachment(transactionId: string, assetId: string) {
    try { await send(`/api/dashboard/workspace/finance/transactions/${transactionId}/attachments`, "DELETE", { assetId }); setNotice("Image detached. The private media asset remains in your library."); await load(); }
    catch (cause) { setError(cause instanceof Error ? cause.message : "Image could not be detached."); }
  }

  const visibleSummary = useMemo(() => data.summary.find((item) => item.currency === currency), [data.summary, currency]);
  const minor = (value: string | number | undefined) => { const normalized = String(value ?? "0").replace(/(\.\d*?[1-9])0+$/, "$1").replace(/\.0+$/, ""); return parseFinanceAmount(normalized || "0", currency); };
  const money = (value: string | number | undefined) => { try { return formatFinanceAmount(minor(value), currency); } catch { return `${currency} —`; } };
  const cashOutflow = minor(visibleSummary?.actualExpenses) + minor(visibleSummary?.debtRepayments);

  return <main className="mx-auto grid w-full max-w-7xl gap-5 px-4 pb-20 pt-7 text-white sm:px-6 lg:px-8">
    <header className="flex flex-wrap items-end justify-between gap-4"><div><p className="text-xs font-semibold uppercase tracking-[.2em] text-[#D9A441]">Personal Intelligence Workspace · Private</p><h1 className="mt-2 text-3xl font-semibold sm:text-4xl">Finance centre</h1><p className="mt-2 max-w-2xl text-sm text-white/55">Your recorded money, obligations and plans, separated by currency and date.</p></div><div className="rounded-full border border-emerald-200/15 bg-emerald-200/[.05] px-3 py-2 text-xs text-emerald-100/80"><ShieldCheck className="mr-2 inline" size={15}/>Owner-only · no bank connections</div></header>
    <WorkspaceSectionNav active="finance" />
    <nav aria-label="Finance sections" className="flex gap-2 overflow-x-auto pb-1">{tabs.map((item) => <button key={item.id} type="button" onClick={() => setTab(item.id)} aria-current={tab === item.id ? "page" : undefined} className={`shrink-0 rounded-full border px-3.5 py-2 text-xs transition ${tab === item.id ? "border-[#D9A441]/40 bg-[#D9A441]/10 text-[#F2CF86]" : "border-white/10 text-white/55 hover:bg-white/[.05]"}`}>{item.label}</button>)}</nav>
    {editingResource && <Panel title={`Edit ${editingResource.resource === "positions" ? "valuation" : editingResource.resource.slice(0, -1)}`} icon={<WalletCards size={17}/>}><form onSubmit={(event) => void submitResourceEdit(event)} className="grid gap-3 sm:grid-cols-2">{(editFields[editingResource.resource] ?? []).map((field) => { const raw = editingResource.record[field.key]; const value = raw == null ? "" : String(raw); const normalized = field.type === "date" ? value.slice(0, 10) : field.type === "datetime-local" ? value.slice(0, 16) : value; return <label key={field.key} className={`${labelClass} ${field.type === "textarea" ? "sm:col-span-2" : ""}`}>{field.label}{field.type === "select" ? <select className={fields} name={field.key} required={field.required} defaultValue={normalized}>{field.options?.map((option) => <option key={option} value={option}>{option}</option>)}</select> : field.type === "textarea" ? <textarea className={`${fields} min-h-20 py-2`} name={field.key} defaultValue={normalized}/> : <input className={fields} name={field.key} type={field.type ?? "text"} required={field.required} defaultValue={normalized} step={field.type === "number" ? "any" : undefined}/>}</label>; })}<div className="flex gap-2 sm:col-span-2"><button className={button} disabled={saving}><Plus size={14}/>Save changes</button><button className={secondary} type="button" onClick={() => setEditingResource(null)}>Cancel</button></div><p className="text-xs leading-5 text-white/40 sm:col-span-2">Edits are owner-scoped and recorded in Finance history. Asset/liability valuation changes keep a revision check and append a dated valuation.</p></form></Panel>}
    <div className="flex flex-wrap items-end gap-3 rounded-2xl border border-white/8 bg-white/[.025] p-4"><label className={labelClass}>From<input className={fields} type="date" value={from} max={to} onChange={(event) => setFrom(event.target.value)}/></label><label className={labelClass}>Through<input className={fields} type="date" value={to} min={from} onChange={(event) => setTo(event.target.value)}/></label><label className={labelClass}>Currency to display<select className={fields} value={currency} onChange={(event) => setCurrency(event.target.value as FinanceCurrency)}>{currencyOptions}</select></label>{tab === "transactions" && <><label className={labelClass}>Record type<select className={fields} value={kindFilter} onChange={(event) => { setKindFilter(event.target.value); setPage(1); }}><option value="">All types</option>{["INCOME", "EXPENSE", "TRANSFER", "SAVINGS_CONTRIBUTION", "SAVINGS_WITHDRAWAL", "DEBT_REPAYMENT", "ASSET_ACQUISITION", "ASSET_DISPOSAL"].map((item) => <option key={item}>{item}</option>)}</select></label><label className={labelClass}>Search<input className={fields} maxLength={100} value={search} onChange={(event) => { setSearch(event.target.value); setPage(1); }} placeholder="Label or category"/></label></>}<button className={button} type="button" onClick={() => { setApplied({ from, to }); setPage(1); }}><RefreshCw size={14}/>Apply range</button><p className="w-full text-xs text-white/40">Amounts in other currencies remain separate; no exchange-rate conversion is applied.</p></div>
    {notice && <p role="status" className="rounded-xl border border-emerald-200/15 bg-emerald-200/[.05] px-4 py-3 text-sm text-emerald-100">{notice}</p>}{error && <div role="alert" className="rounded-xl border border-rose-200/15 bg-rose-200/[.05] px-4 py-3 text-sm text-rose-100">{error}<button type="button" className="ml-3 underline" onClick={() => void load()}>Retry</button></div>}
    {loading && <div role="status" className="rounded-2xl border border-white/8 p-6 text-sm text-white/55">Loading your saved finance records…</div>}
    {!loading && !error && !data.workspace && <div className="rounded-2xl border border-white/10 bg-white/[.03] p-5 text-sm text-white/60">Your Workspace has no finance records yet. Save your first entry below; a Workspace will be created for your authenticated account.</div>}

    {!loading && tab === "overview" && <div className="grid gap-4 md:grid-cols-2 xl:grid-cols-3">
      <Metric icon={<Landmark size={17}/>} title="Assets" value={money(visibleSummary?.actualAssets)} note={`Estimated ${money(visibleSummary?.estimatedAssets)} · estimates shown separately`}/>
      <Metric icon={<CreditCard size={17}/>} title="Liabilities" value={money(visibleSummary?.actualLiabilities)} note="Recorded debt and liability positions; avoid entering the same debt twice"/>
      <Metric icon={<CircleDollarSign size={17}/>} title="Recorded net worth" value={formatFinanceAmount(minor(visibleSummary?.actualAssets) - minor(visibleSummary?.actualLiabilities), currency)} note="Only values in the selected currency; no exchange-rate conversion"/>
      <Metric icon={<ArrowUpRight size={17}/>} title="Income · selected range" value={money(visibleSummary?.actualIncome)} note={`Estimated ${money(visibleSummary?.estimatedIncome)} · planned ${money(visibleSummary?.plannedIncome)}`}/>
      <Metric icon={<ArrowDownLeft size={17}/>} title="Cash outflow · selected range" value={formatFinanceAmount(cashOutflow, currency)} note={`Expenses ${money(visibleSummary?.actualExpenses)} + debt repayments ${money(visibleSummary?.debtRepayments)} · estimates ${money(visibleSummary?.estimatedExpenses)} · planned ${money(visibleSummary?.plannedExpenses)}`}/>
      <Metric icon={<Activity size={17}/>} title="Net cash flow" value={formatFinanceAmount(minor(visibleSummary?.actualIncome) - cashOutflow, currency)} note={`Actual income less recorded expenses and debt repayments; savings contributions ${money(visibleSummary?.savingsContributions)} are shown separately.`}/>
      <LiquidLensSurface radius={22} className="p-5 md:col-span-2"><div className="flex items-center gap-2 text-[#F2CF86]"><Target size={17}/><h2 className="text-sm font-medium text-white">Savings goals</h2></div>{data.goals.length ? <div className="mt-4 grid gap-3 sm:grid-cols-2">{data.goals.slice(0, 6).map((goal) => <div key={goal.id} className="rounded-xl border border-white/8 p-3"><div className="flex justify-between gap-3 text-sm"><span>{goal.name}</span><span className="tabular-nums text-white/60">{goal.progressPercent.toFixed(1)}%</span></div><div className="mt-3 h-1.5 overflow-hidden rounded-full bg-white/10"><div className="h-full rounded-full bg-emerald-200" style={{ width: `${Math.min(100, goal.progressPercent)}%` }}/></div><p className="mt-2 text-xs text-white/45">{goal.currency} · {goal.status.toLowerCase()}</p></div>)}</div> : <Empty>No saved goals yet.</Empty>}</LiquidLensSurface>
      <LiquidLensSurface radius={22} className="p-5"><div className="flex items-center gap-2 text-[#F2CF86]"><CalendarClock size={17}/><h2 className="text-sm font-medium text-white">Upcoming reminders</h2></div>{data.reminders.length ? <ul className="mt-3 grid gap-3">{data.reminders.slice(0, 5).map((item) => <li key={item.id} className="text-sm">{item.title}<p className="text-xs text-white/45">{new Date(item.remindAt).toLocaleString()} · personal reminder</p></li>)}</ul> : <Empty>No reminders recorded.</Empty>}</LiquidLensSurface>
      <LiquidLensSurface radius={22} className="p-5 md:col-span-2 xl:col-span-3"><h2 className="text-sm font-medium">Budget utilisation</h2>{data.budgets.length ? <div className="mt-4 grid gap-3 md:grid-cols-2">{data.budgets.slice(0, 8).map((budget) => <div key={budget.id} className="rounded-xl border border-white/8 p-3"><div className="flex justify-between gap-3 text-sm"><span>{budget.category}</span><span className="text-xs text-white/55">{budget.currency} · {budget.percent.toFixed(1)}%</span></div><div className="mt-2 h-1.5 overflow-hidden rounded-full bg-white/10"><div className={`h-full ${budget.percent > 100 ? "bg-rose-300" : "bg-[#D9A441]"}`} style={{ width: `${Math.min(100, budget.percent)}%` }}/></div><p className="mt-2 text-xs text-white/45">{budget.remaining.startsWith("-") ? `${budget.currency} ${budget.remaining.slice(1)} over` : `${budget.currency} ${budget.remaining} remaining`} · ends {budget.endsOn.slice(0, 10)}</p>{budget.calculationTruncated && <p className="text-xs text-amber-200">Calculation is bounded and incomplete for this period.</p>}</div>)}</div> : <Empty>No active budgets overlap the selected period.</Empty>}</LiquidLensSurface>
      <LiquidLensSurface radius={22} className="p-5 md:col-span-2 xl:col-span-3"><h2 className="text-sm font-medium">Currency-separated recorded totals</h2><div className="mt-3 flex flex-wrap gap-2">{data.summary.length ? data.summary.map((item) => <button key={String(item.currency)} onClick={() => setCurrency(String(item.currency) as FinanceCurrency)} className={secondary} type="button">{String(item.currency)} · {String(item.recordedTransactions ?? 0)} ledger entries</button>) : <Empty>No activity has been recorded in this date range.</Empty>}</div></LiquidLensSurface>
    </div>}

    {!loading && tab === "transactions" && <div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><Panel title={editing ? "Edit transaction" : "New ledger entry"} icon={<WalletCards size={17}/>}><form onSubmit={(event) => { event.preventDefault(); const form = event.currentTarget; const values = Object.fromEntries(new FormData(form).entries()); const draft = { kind: values.kind, quality: values.quality, amount: values.amount, currency: values.currency, occurredOn: values.occurredOn, label: values.label, category: values.category, subcategory: values.subcategory || null, paymentMethod: values.paymentMethod || null, description: values.description || null, notes: values.notes || null, fromAccount: values.fromAccount || null, toAccount: values.toAccount || null }; setSaving(true); setError(""); void (async () => { try { if (editing) await send(`/api/dashboard/workspace/finance/transactions/${editing.id}`, "PATCH", { data: draft }); else await send("/api/dashboard/workspace/finance", "POST", { resource: "transactions", data: draft }); setEditing(null); setNotice("Ledger entry saved."); await load(); } catch (cause) { setError(cause instanceof Error ? cause.message : "Could not save transaction."); } finally { setSaving(false); } })(); }} className="grid gap-3 sm:grid-cols-2"><label className={labelClass}>Type<select className={fields} name="kind" defaultValue={editing?.kind ?? "EXPENSE"}>{["INCOME", "EXPENSE", "TRANSFER", "ASSET_ACQUISITION", "ASSET_DISPOSAL"].map((x) => <option key={x}>{x}</option>)}</select></label><label className={labelClass}>Quality<select className={fields} name="quality" defaultValue={editing?.quality ?? "ACTUAL"}><option>ACTUAL</option><option>PLANNED</option></select></label><label className={labelClass}>Amount<input className={fields} name="amount" inputMode="decimal" required defaultValue={editing?.amount} placeholder="0.00"/></label><label className={labelClass}>Currency<select className={fields} name="currency" defaultValue={editing?.currency ?? currency}>{currencyOptions}</select></label><label className={labelClass}>Date<input className={fields} name="occurredOn" type="date" required defaultValue={editing?.occurredOn.slice(0, 10) ?? today}/></label><label className={labelClass}>Label<input className={fields} name="label" maxLength={120} required defaultValue={editing?.label}/></label><label className={labelClass}>Category<input className={fields} name="category" maxLength={64} required defaultValue={editing?.category}/></label><label className={labelClass}>Payment method<input className={fields} name="paymentMethod" maxLength={48} defaultValue={editing?.paymentMethod ?? ""}/></label><label className={labelClass}>From account label<input className={fields} name="fromAccount" maxLength={80} defaultValue={editing?.fromAccount ?? ""}/></label><label className={labelClass}>To account label<input className={fields} name="toAccount" maxLength={80} defaultValue={editing?.toAccount ?? ""}/></label><label className={`${labelClass} sm:col-span-2`}>Description<textarea className={`${fields} min-h-20 py-2`} name="description" maxLength={500} defaultValue={editing?.description ?? ""}/></label><label className={`${labelClass} sm:col-span-2`}>Private notes<textarea className={`${fields} min-h-20 py-2`} name="notes" maxLength={2000} defaultValue={editing?.notes ?? ""}/></label><div className="flex gap-2 sm:col-span-2"><button disabled={saving} className={button}><Plus size={15}/>{editing ? "Save changes" : "Save entry"}</button>{editing && <button type="button" className={secondary} onClick={() => setEditing(null)}>Cancel</button>}</div></form><p className="mt-3 text-xs leading-5 text-white/40">Transfers need different from/to account labels and do not count as income or expenditure. Linked savings/debt actions must be recorded in their own sections.</p></Panel>
      <Panel title={`Ledger · ${data.transactions.total} entries`} icon={<Activity size={17}/>}><div className="overflow-x-auto"><table className="w-full min-w-[650px] text-left text-sm"><thead className="text-xs text-white/40"><tr><th className="pb-3">Date / entry</th><th>Category</th><th>Type</th><th className="text-right">Amount</th><th/></tr></thead><tbody>{data.transactions.items.map((row) => <tr key={row.id} className="border-t border-white/8 align-top"><td className="py-3"><span className="block">{row.label}</span><span className="text-xs text-white/40">{row.occurredOn.slice(0, 10)}</span>{row.attachments?.map((attachment) => <div key={attachment.id} className="mt-1 flex gap-2 text-[11px]"><a className="text-[#F2CF86] underline" href={`/api/dashboard/workspace/media/${attachment.mediaAsset.id}`} target="_blank" rel="noreferrer">Private image · {Math.ceil(attachment.mediaAsset.byteSize / 1024)} KB</a><button type="button" className="text-white/45 underline" onClick={() => void detachAttachment(row.id, attachment.mediaAsset.id)}>Detach</button></div>)}<label className="mt-2 block text-[11px] text-white/40">Attach private image<input className="mt-1 block max-w-48 text-xs" type="file" accept="image/jpeg,image/png,image/webp" disabled={saving} onChange={(event) => { const file = event.target.files?.[0]; if (file) void uploadAttachment(row.id, file); event.currentTarget.value = ""; }}/></label></td><td className="py-3 text-white/55">{row.category}</td><td className="py-3 text-xs text-white/50">{row.kind.replaceAll("_", " ")} · {row.quality.toLowerCase()}</td><td className="py-3 text-right tabular-nums">{row.currency} {row.amount}</td><td className="py-3"><div className="flex justify-end gap-2"><button className={secondary} type="button" onClick={() => { setEditing(row); window.scrollTo({ top: 0, behavior: "smooth" }); }}>Edit</button><button className={secondary} type="button" onClick={() => void archive("transactions", row.id)} aria-label={`Archive ${row.label}`}><Archive size={13}/></button></div></td></tr>)}</tbody></table></div>{!data.transactions.items.length && <Empty>No ledger entries in this date range. Add your own record; no amounts are inferred.</Empty>}<div className="mt-4 flex justify-between text-xs text-white/45"><span>Page {data.transactions.page} · {data.transactions.total} saved</span><div className="flex gap-2"><button className={secondary} disabled={page <= 1} onClick={() => setPage((value) => value - 1)}>Previous</button><button className={secondary} disabled={page * 25 >= data.transactions.total} onClick={() => setPage((value) => value + 1)}>Next</button></div></div></Panel></div>}

    {!loading && tab === "positions" && <div className="grid gap-5 xl:grid-cols-[.8fr_1.2fr]"><Panel title={editingPosition ? "Add valuation to position" : "Record a valuation"} icon={<Landmark size={17}/>}><form key={editingPosition?.id ?? "new-position"} onSubmit={(event) => void submit(event, "positions")} className="grid gap-3 sm:grid-cols-2"><label className={labelClass}>Position type<select className={fields} name="kind" defaultValue={editingPosition?.kind ?? "ASSET"}><option>ASSET</option><option>LIABILITY</option></select></label><label className={labelClass}>Valuation quality<select className={fields} name="quality" defaultValue={editingPosition?.quality ?? "ACTUAL"}><option>ACTUAL</option><option>ESTIMATE</option></select></label><Field name="label" title="Name" required defaultValue={editingPosition?.label}/><Field name="category" title="Category" required defaultValue={editingPosition?.category}/><Field name="value" title="Current value" type="number" required defaultValue={editingPosition?.value}/><label className={labelClass}>Currency<select className={fields} name="currency" defaultValue={editingPosition?.currency ?? currency} disabled={Boolean(editingPosition)}>{currencyOptions}</select>{editingPosition && <input type="hidden" name="currency" value={editingPosition.currency}/>}</label><Field name="valuedOn" title="Valuation date" type="date" defaultValue={editingPosition?.valuedOn.slice(0, 10) ?? today} required/><label className={`${labelClass} sm:col-span-2`}>Private notes<textarea className={`${fields} min-h-20 py-2`} name="notes" maxLength={2000}/></label><div className="flex gap-2"><button className={button} disabled={saving}><Plus size={14}/>{editingPosition ? "Save valuation" : "Save position"}</button>{editingPosition && <button type="button" className={secondary} onClick={() => setEditingPosition(null)}>Cancel</button>}</div></form><p className="mt-3 text-xs text-white/40">Each update appends a dated valuation. Values remain in their original currency.</p></Panel><Panel title="Assets & liabilities" icon={<CreditCard size={17}/>}><div className="grid gap-3">{data.positions.map((position) => <article key={position.id} className="rounded-xl border border-white/8 p-4"><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-xs text-white/45">{position.kind} · {position.category} · {position.quality.toLowerCase()}</p><h3 className="mt-1 font-medium">{position.label}</h3><p className="mt-1 text-sm tabular-nums">{position.currency} {position.value} <span className="text-xs text-white/40">valued {position.valuedOn.slice(0, 10)}</span></p></div><div className="flex gap-2"><button className={secondary} type="button" onClick={() => startResourceEdit("positions", position.id, position as unknown as Record<string, unknown>)}>Edit details</button><button className={secondary} type="button" onClick={() => setEditingPosition(position)}>New valuation</button><button className={secondary} type="button" onClick={() => void archive("positions", position.id)}>Archive</button></div></div><div className="mt-3 border-t border-white/8 pt-3"><p className="text-xs text-white/40">Valuation history</p><div className="mt-2 flex flex-wrap gap-2">{position.valuations.map((item) => <span key={item.id} className="rounded-lg bg-white/[.04] px-2 py-1 text-xs text-white/55">{item.valuedOn.slice(0, 10)} · {position.currency} {item.value} · {item.quality.toLowerCase()}</span>)}</div></div></article>)}{!data.positions.length && <Empty>No asset or liability valuations recorded.</Empty>}</div></Panel></div>}

    {!loading && tab === "budgets" && <div className="grid gap-5 lg:grid-cols-[.7fr_1.3fr]"><Panel title="Create budget" icon={<WalletCards size={17}/>}><form onSubmit={(event) => void submit(event, "budgets")} className="grid gap-3"><Field name="name" title="Budget name" required/><Field name="category" title="Expense category" required/><label className={labelClass}>Currency<select className={fields} name="currency" defaultValue={currency}>{currencyOptions}</select></label><Field name="limitAmount" title="Period limit" type="number" required/><Field name="startsOn" title="Starts" type="date" defaultValue={today.slice(0, 7) + "-01"} required/><Field name="endsOn" title="Ends" type="date" defaultValue={today} required/><button className={button} disabled={saving}><Plus size={14}/>Save budget</button></form></Panel><Panel title="Period budgets" icon={<Activity size={17}/>}><div className="grid gap-3 md:grid-cols-2">{data.budgets.map((budget) => <article key={budget.id} className="rounded-xl border border-white/8 p-4"><div className="flex justify-between gap-3"><div><p className="text-xs text-white/45">{budget.name} · {budget.currency}</p><h3 className="mt-1 font-medium">{budget.category}</h3></div><div className="flex gap-2"><button className={secondary} type="button" onClick={() => startResourceEdit("budgets", budget.id, budget as unknown as Record<string, unknown>)}>Edit</button><button className={secondary} type="button" onClick={() => void archive("budgets", budget.id)}>Archive</button></div></div><p className="mt-3 text-sm tabular-nums">{budget.currency} {budget.spent} / {budget.limitAmount}</p><div className="mt-2 h-2 overflow-hidden rounded-full bg-white/10"><div className={`h-full ${budget.percent > 100 ? "bg-rose-300" : "bg-[#D9A441]"}`} style={{ width: `${Math.min(100, budget.percent)}%` }}/></div><p className="mt-2 text-xs text-white/45">{budget.percent.toFixed(1)}% · {budget.remaining} remaining · {budget.startsOn.slice(0, 10)} to {budget.endsOn.slice(0, 10)}</p>{budget.calculationTruncated && <p className="mt-1 text-xs text-amber-200">Showing bounded results; full utilisation may be higher.</p>}</article>)}{!data.budgets.length && <Empty>No budgets overlap the selected date range.</Empty>}</div></Panel></div>}

    {!loading && tab === "goals" && <div className="grid gap-5 lg:grid-cols-[.7fr_1.3fr]"><Panel title="Create savings goal" icon={<Target size={17}/>}><form onSubmit={(event) => void submit(event, "goals")} className="grid gap-3"><Field name="name" title="Goal name" required/><label className={labelClass}>Description<textarea className={`${fields} min-h-20 py-2`} name="description" maxLength={1000}/></label><label className={labelClass}>Currency<select className={fields} name="currency" defaultValue={currency}>{currencyOptions}</select></label><Field name="targetAmount" title="Target amount" type="number" required/><Field name="targetOn" title="Target date" type="date"/><button className={button} disabled={saving}><Plus size={14}/>Save goal</button></form></Panel><Panel title="Goals & contribution history" icon={<Target size={17}/>}><div className="grid gap-4">{data.goals.map((goal) => <article key={goal.id} className="rounded-xl border border-white/8 p-4"><div className="flex flex-wrap justify-between gap-3"><div><h3 className="font-medium">{goal.name}</h3><p className="mt-1 text-xs text-white/45">{goal.currency} · target {goal.targetOn?.slice(0, 10) ?? "date not set"}</p></div><div className="flex gap-2"><button className={secondary} type="button" onClick={() => startResourceEdit("goals", goal.id, goal as unknown as Record<string, unknown>)}>Edit</button><button className={secondary} type="button" onClick={() => void archive("goals", goal.id)}>Archive</button></div></div><p className="mt-3 text-sm tabular-nums">{goal.currency} {goal.currentAmount} / {goal.targetAmount} · {goal.progressPercent.toFixed(1)}%</p><div className="mt-2 h-2 rounded-full bg-white/10"><div className="h-full rounded-full bg-emerald-200" style={{ width: `${Math.min(100, goal.progressPercent)}%` }}/></div><form className="mt-3 grid gap-2 sm:grid-cols-[1fr_1fr_auto]" onSubmit={(event) => { event.preventDefault(); const form = event.currentTarget; const values = Object.fromEntries(new FormData(form).entries()); void action({ action: "goalMovement", goalId: goal.id, kind: values.kind, amount: values.amount, occurredOn: values.occurredOn }); form.reset(); }}><select name="kind" className={fields}><option value="CONTRIBUTION">Contribution</option><option value="WITHDRAWAL">Withdrawal</option></select><input name="amount" required inputMode="decimal" className={fields} placeholder={`Amount (${goal.currency})`}/><button className={secondary} disabled={saving}>Record</button><input name="occurredOn" type="date" defaultValue={today} required className={`${fields} sm:col-span-3`}/></form>{goal.movements?.length ? <ul aria-label={goal.name + " contribution history"} className="mt-3 grid gap-1 border-t border-white/8 pt-3 text-xs text-white/45">{goal.movements.slice(0, 8).map((movement) => <li key={movement.id} className="flex justify-between gap-3"><span>{movement.occurredOn.slice(0, 10)} · {movement.kind.toLowerCase()}</span><span>{goal.currency} {movement.amount}</span></li>)}</ul> : null}</article>)}{!data.goals.length && <Empty>No savings goals recorded.</Empty>}</div></Panel></div>}

    {!loading && tab === "debts" && <div className="grid gap-5 lg:grid-cols-[.7fr_1.3fr]"><Panel title="Record an obligation" icon={<CreditCard size={17}/>}><form onSubmit={(event) => void submit(event, "debts")} className="grid gap-3"><Field name="name" title="Debt name" required/><Field name="lenderDescription" title="Lender description"/><label className={labelClass}>Currency<select className={fields} name="currency" defaultValue={currency}>{currencyOptions}</select></label><Field name="originalPrincipal" title="Original principal" type="number" required/><Field name="outstandingBalance" title="Outstanding balance" type="number" required/><Field name="annualInterestRate" title="Annual rate (%)" type="number"/><label className={labelClass}>Rate type<select className={fields} name="interestType"><option>UNKNOWN</option><option>FIXED</option><option>VARIABLE</option></select></label><label className={labelClass}>Repayment frequency<select className={fields} name="repaymentFrequency">{["IRREGULAR", "WEEKLY", "BIWEEKLY", "MONTHLY", "QUARTERLY", "ANNUAL"].map((item) => <option key={item}>{item}</option>)}</select></label><Field name="repaymentAmount" title="Expected repayment" type="number"/><Field name="nextDueOn" title="Next due date" type="date"/><label className={`${labelClass} sm:col-span-2`}>Private assumptions/notes<textarea className={`${fields} min-h-16 py-2`} name="notes" maxLength={2000}/></label><button className={button} disabled={saving}><Plus size={14}/>Save debt</button></form></Panel><Panel title="Debt position & repayments" icon={<CreditCard size={17}/>}><div className="grid gap-3">{data.debts.map((debt) => <article key={debt.id} className="rounded-xl border border-white/8 p-4"><div className="flex justify-between gap-3"><div><h3 className="font-medium">{debt.name}</h3><p className="mt-1 text-xs text-white/45">{debt.currency} · {debt.interestType.toLowerCase()} · {debt.repaymentFrequency.toLowerCase()}</p></div><div className="flex gap-2"><button className={secondary} type="button" onClick={() => startResourceEdit("debts", debt.id, debt as unknown as Record<string, unknown>)}>Edit</button><button className={secondary} type="button" onClick={() => void archive("debts", debt.id)}>Archive</button></div></div><p className="mt-3 text-sm tabular-nums">Outstanding {debt.currency} {debt.outstandingBalance} <span className="text-white/40">of {debt.currency} {debt.originalPrincipal}</span></p><DebtEstimate debt={debt}/><form className="mt-3 grid gap-2 sm:grid-cols-2" onSubmit={(event) => { event.preventDefault(); const form = event.currentTarget; const values = Object.fromEntries(new FormData(form).entries()); void action({ action: "debtPayment", debtId: debt.id, amount: values.amount, principalAmount: values.principalAmount, interestAmount: values.interestAmount, occurredOn: values.occurredOn }); form.reset(); }}><input className={fields} name="principalAmount" inputMode="decimal" required placeholder="Principal portion"/><input className={fields} name="interestAmount" inputMode="decimal" required placeholder="Interest portion"/><input className={fields} name="amount" inputMode="decimal" required placeholder="Total paid"/><input className={fields} name="occurredOn" type="date" defaultValue={today} required/><button className={`${secondary} sm:col-span-2`} disabled={saving}>Record repayment</button></form>{debt.payments?.length ? <ul aria-label={debt.name + " repayment history"} className="mt-3 grid gap-1 border-t border-white/8 pt-3 text-xs text-white/45">{debt.payments.slice(0, 8).map((payment) => <li key={payment.id} className="flex flex-wrap justify-between gap-2"><span>{payment.occurredOn.slice(0, 10)} · principal {debt.currency} {payment.principalAmount} · interest {debt.currency} {payment.interestAmount}</span><span>paid {debt.currency} {payment.transaction.amount}</span></li>)}</ul> : null}</article>)}{!data.debts.length && <Empty>No debt records have been entered.</Empty>}</div></Panel></div>}

    {!loading && tab === "recurring" && <div className="grid gap-5 lg:grid-cols-[.7fr_1.3fr]"><Panel title="Recurring commitment" icon={<RefreshCw size={17}/>}><form onSubmit={(event) => void submit(event, "recurring")} className="grid gap-3"><label className={labelClass}>Type<select name="kind" className={fields}><option>EXPENSE</option><option>INCOME</option><option>TRANSFER</option></select></label><Field name="label" title="Label" required/><Field name="category" title="Category" required/><Field name="amount" title="Amount" type="number" required/><label className={labelClass}>Currency<select className={fields} name="currency" defaultValue={currency}>{currencyOptions}</select></label><label className={labelClass}>Frequency<select className={fields} name="frequency"><option>MONTHLY</option><option>WEEKLY</option><option>ANNUAL</option></select></label><Field name="interval" title="Every N periods" type="number" defaultValue="1" required/><Field name="nextOn" title="Next occurrence" type="date" defaultValue={today} required/><button className={button} disabled={saving}><Plus size={14}/>Save schedule</button></form><p className="mt-3 text-xs leading-5 text-white/40">Schedules do not create ledger entries automatically. Record each occurrence explicitly to prevent duplicate or unintended transactions.</p></Panel><Panel title="Upcoming schedules" icon={<CalendarClock size={17}/>}><div className="grid gap-3">{data.recurring.map((item) => <article key={item.id} className="flex flex-wrap items-center justify-between gap-3 rounded-xl border border-white/8 p-4"><div><h3 className="font-medium">{item.label}</h3><p className="mt-1 text-xs text-white/45">{item.currency} {item.amount} · {item.frequency.toLowerCase()} · next {item.nextOn.slice(0, 10)} · {item.quality.toLowerCase()}</p></div><div className="flex gap-2"><button className={secondary} type="button" disabled={!item.active || saving} onClick={() => void action({ action: "recurringOccurrence", scheduleId: item.id })}>Record next occurrence</button><button className={secondary} type="button" onClick={() => startResourceEdit("recurring", item.id, item as unknown as Record<string, unknown>)}>Edit</button><button className={secondary} type="button" disabled={saving} onClick={() => void setRecurringActive(item.id, !item.active)}>{item.active ? "Pause" : "Resume"}</button></div></article>)}{!data.recurring.length && <Empty>No recurring commitments saved.</Empty>}</div></Panel></div>}

    {!loading && tab === "reminders" && <div className="grid gap-5 lg:grid-cols-[.7fr_1.3fr]"><Panel title="Add a personal reminder" icon={<CalendarClock size={17}/>}><form onSubmit={(event) => void submit(event, "reminders")} className="grid gap-3"><label className={labelClass}>Reminder kind<select className={fields} name="kind">{["BILL_PAYMENT", "DEBT_REPAYMENT", "SAVINGS_CONTRIBUTION", "FINANCIAL_REVIEW", "BUDGET_CHECK_IN"].map((item) => <option key={item}>{item}</option>)}</select></label><Field name="title" title="Reminder" required/><Field name="remindAt" title="Date and time" type="datetime-local" required/><Field name="taskId" title="Optional existing task ID"/><button className={button} disabled={saving}><Plus size={14}/>Save reminder</button></form><p className="mt-3 text-xs leading-5 text-white/40">Saving a reminder is explicit consent to place it in your Workspace calendar. The existing application has no finance-specific push/email delivery service; this record does not promise a notification outside the app.</p></Panel><Panel title="Scheduled reminders" icon={<CalendarClock size={17}/>}><div className="grid gap-3">{data.reminders.map((item) => <article key={item.id} className="flex flex-wrap justify-between gap-3 rounded-xl border border-white/8 p-4"><div><h3 className="font-medium">{item.title}</h3><p className="mt-1 text-xs text-white/45">{item.kind.toLowerCase().replaceAll("_", " ")} · {new Date(item.remindAt).toLocaleString()} ({item.timezone}){item.taskId ? " · linked to task" : ""}</p></div><div className="flex gap-2"><button type="button" className={secondary} onClick={() => startResourceEdit("reminders", item.id, item as unknown as Record<string, unknown>)}>Edit</button><button type="button" className={secondary} onClick={() => void archive("reminders", item.id)}>Dismiss</button></div></article>)}{!data.reminders.length && <Empty>No personal finance reminders are scheduled.</Empty>}</div></Panel></div>}

    {!loading && tab === "overview" && <Panel title="Recent private activity" icon={<ShieldCheck size={17}/>}><ul className="grid gap-2 sm:grid-cols-2">{data.history.slice(0, 12).map((item) => <li key={item.id} className="rounded-xl border border-white/8 p-3"><p className="text-sm">{item.action.replaceAll("_", " ").toLowerCase()}</p><p className="mt-1 text-xs text-white/40">{item.targetType.toLowerCase()} · {item.changedFields.join(", ")} · {new Date(item.createdAt).toLocaleString()}</p></li>)}{!data.history.length && <Empty>No finance changes recorded yet.</Empty>}</ul><p className="mt-3 text-xs text-white/35">History stores action, target and changed field names only; it does not copy monetary values or notes.</p></Panel>}
    {!loading && error && <p className="text-xs text-white/40">Saved data is not replaced by mock values. Retry after access is restored.</p>}
    <footer className="rounded-2xl border border-white/8 bg-white/[.02] p-4 text-xs leading-5 text-white/40">Private workspace data · no financial institution connection · no exchange-rate conversion · records and valuations are user-entered. Budget and debt calculations are descriptive only and are not financial advice.</footer>
  </main>;
}

function Metric({ icon, title, value, note }: { icon: React.ReactNode; title: string; value: string; note: string }) { return <LiquidLensSurface radius={22} className="p-5"><div className="flex items-center gap-2 text-[#F2CF86]">{icon}<h2 className="text-xs uppercase tracking-[.12em] text-white/55">{title}</h2></div><p className="mt-3 text-2xl font-semibold tabular-nums">{value}</p><p className="mt-2 text-xs leading-5 text-white/40">{note}</p></LiquidLensSurface>; }
function Panel({ title, icon, children }: { title: string; icon: React.ReactNode; children: React.ReactNode }) { return <LiquidLensSurface radius={23} className="p-4 sm:p-5"><div className="mb-4 flex items-center gap-2 text-[#F2CF86]">{icon}<h2 className="text-base font-semibold text-white">{title}</h2></div>{children}</LiquidLensSurface>; }
function Empty({ children }: { children: React.ReactNode }) { return <p className="rounded-xl border border-dashed border-white/10 p-4 text-sm text-white/40">{children}</p>; }
function Field({ name, title, type = "text", required = false, defaultValue, min, step }: { name: string; title: string; type?: string; required?: boolean; defaultValue?: string; min?: string; step?: string }) { return <label className={labelClass}>{title}<input className={fields} name={name} type={type} required={required} defaultValue={defaultValue} min={min} step={step ?? (type === "number" ? "any" : undefined)}/></label>; }
function DebtEstimate({ debt }: { debt: Debt }) { const result = useMemo(() => { if (!debt.annualInterestRate || !debt.repaymentAmount) return null; const estimate = estimateMonthlyDebtPayoff({ balance: debt.outstandingBalance, payment: debt.repaymentAmount, annualRatePercent: debt.annualInterestRate, currency: debt.currency, fixedRate: debt.interestType === "FIXED", monthlyFrequency: debt.repaymentFrequency === "MONTHLY" }); if (!estimate) return null; const date = new Date(); const target = new Date(Date.UTC(date.getUTCFullYear(), date.getUTCMonth() + estimate.months, 1)); return { ...estimate, targetMonth: target.toISOString().slice(0, 7) }; }, [debt]); return <p className="mt-2 text-xs text-white/40">{result ? `Illustrative payoff: about ${result.months} monthly payments by ${result.targetMonth}; estimated interest ${formatFinanceAmount(result.totalInterestMinor, debt.currency)}. Assumes fixed annual rate, unchanged monthly payment and monthly half-up interest rounding.` : "Payoff estimate unavailable: enter a fixed annual rate and monthly payment that reduces the balance. Variable, unknown, or non-monthly terms are not projected."}</p>; }
